<script setup lang="ts">
import {locale,tr} from '../lib/i18n'
import { computed, ref, onMounted, onUnmounted, watch } from 'vue'
import ProfileFlow from './ProfileFlow.vue'
import ReplyTopup from './ReplyTopup.vue'
import InboxFlow from './InboxFlow.vue'
import LettersFlow, { type Letter } from './LettersFlow.vue'
import { api, ApiError } from '../lib/api'
import { asset } from '../lib/assets'
const props=defineProps<{token:string}>()
const emit=defineEmits<{signin:[]}>()
type Pass={active:boolean;expiresAt:string|null;remainingDays:number;plans:{days:number;diamonds:number}[]}
const sheet=ref(''),error=ref(''),busy=ref(false),items=ref<Letter[]>([]),responses=ref<{openingMessageId:string}[]>([]),detail=ref<Letter>(),loaded=ref(false)
const pass=ref<Pass>({active:false,expiresAt:null,remainingDays:0,plans:[]}), now=ref(Date.now()),cities=ref<string[]>([])
const passBalance=ref(0),passTopup=ref(false),passNotice=ref('')
const selectedPlan=ref<Pass['plans'][number]>(),purchaseKey=ref('')
const validUntil=computed(()=>new Date(Math.max(now.value,new Date(pass.value.expiresAt||0).getTime())+(selectedPlan.value?.days||0)*86400000).toLocaleString(locale.value==='ko'?'ko-KR':'en-US'))
const active=computed(()=>pass.value.active&&!!pass.value.expiresAt&&new Date(pass.value.expiresAt).getTime()>now.value)
const days=computed(()=>active.value?Math.ceil((new Date(pass.value.expiresAt!).getTime()-now.value)/86400000):0)
const gender=ref(''),city=ref(''),min=ref(18),max=ref(50),ageSet=ref(false)
const filters=computed(()=>({...(gender.value?{gender:gender.value}:{}),...(active.value&&city.value?{city:city.value}:{}),...(active.value&&ageSet.value?{minAge:min.value,...(max.value<50?{maxAge:max.value}:{})}:{})}))
const birdGender=ref('female'),variant=ref(1),motion=ref(true),trails=ref(true)
try{const p=JSON.parse(localStorage.getItem('maugo-bird')||'{}');if(['male','female'].includes(p.gender))birdGender.value=p.gender;if(Number.isInteger(p.variant)&&p.variant>=1&&p.variant<=9)variant.value=p.variant;motion.value=p.motion!==false;trails.value=p.trails!==false}catch{}
watch([birdGender,variant,motion,trails],()=>localStorage.setItem('maugo-bird',JSON.stringify({gender:birdGender.value,variant:variant.value,motion:motion.value,trails:trails.value})))
const variants=['Sky blue','Sunshine','Sage green','Soft lilac','Fresh mint','Sunset peach','Blueberry blush','Pastel rainbow','Aurora']
const bird=computed(()=>asset(`02-bird-static/${birdGender.value}-${variant.value}`))
const flight=computed(()=>asset(`03-bird-flight-sheets/${birdGender.value}-${variant.value}-fly`))
const headers=()=>({Authorization:`Bearer ${props.token}`})
async function request<T>(path:string,body?:object,extra?:Record<string,string>){return api<T>(path,{method:body?'POST':'GET',headers:{...headers(),...(body?{'Content-Type':'application/json'}:{}),...extra},...(body?{body:JSON.stringify(body)}:{})})}
async function status(){const [p,f]=await Promise.all([request<Pass>('/filter-pass'),request<{cities:string[]}>('/discovery/filters')]);pass.value=p;cities.value=f.cities;now.value=Date.now()}
async function load(refresh=false){if(busy.value)return;if(!props.token){error.value='Sign in to meet your letters.';return}busy.value=true;error.value='';try{await status();const data=await request<{items:Letter[];responses:{openingMessageId:string}[];locked?:boolean}>(refresh?'/letters/refresh':`/letters?${new URLSearchParams(Object.entries(filters.value).map(([k,v])=>[k,String(v)]))}`,refresh?filters.value:undefined);if(data.locked){pass.value.active=false;city.value='';ageSet.value=false;throw new Error('Your Filter Pass has expired. Please try again.')}items.value=data.items;responses.value=data.responses||[];loaded.value=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function openLetter(id:string){error.value='';try{detail.value=await request<Letter>(`/letters/${id}`);responses.value=responses.value.filter(r=>r.openingMessageId!==id);sheet.value='letter'}catch(e){error.value=(e as Error).message}}
async function openFilters(){sheet.value='filters';if(props.token)try{await status()}catch(e){error.value=(e as Error).message}}
async function confirmPlan(plan:Pass['plans'][number]){if(busy.value)return;if(selectedPlan.value?.days!==plan.days||!purchaseKey.value)purchaseKey.value=crypto.randomUUID();selectedPlan.value=plan;error.value='';passNotice.value='';busy.value=true;try{passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds;sheet.value='pass-confirm'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function closeSheet(){if(busy.value&&sheet.value==='pass-confirm')return;if(['pass','pass-confirm'].includes(sheet.value)){error.value='';sheet.value='filters'}else sheet.value=''}
async function returnToPass(funded=false){passTopup.value=false;sheet.value='pass-confirm';passNotice.value=funded?'Diamonds added. Confirm your selected Pass to continue.':'Top-up closed. No Pass purchased; selection saved.';try{passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds}catch(e){error.value=(e as Error).message}}
async function purchase(days:number){if(busy.value)return;busy.value=true;error.value='';try{pass.value={...pass.value,...await request<Pass>('/filter-pass/purchase',{days},{'Idempotency-Key':purchaseKey.value})};purchaseKey.value='';selectedPlan.value=undefined;sheet.value='filters'}catch(e){if(e instanceof ApiError&&e.status===402){passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds;passNotice.value='Not enough diamonds. Add diamonds to continue.'}else error.value=(e as Error).message}finally{busy.value=false}}
watch(active,(value,old)=>{if(old&&!value){city.value='';ageSet.value=false;min.value=18;max.value=50;if(!busy.value)void load()}})
const tick=setInterval(()=>{now.value=Date.now()},500)
function escape(e:KeyboardEvent){if(e.key==='Escape'&&!passTopup.value&&!['letter','compose','inbox'].includes(sheet.value))closeSheet()}
onMounted(()=>{void load();document.addEventListener('keydown',escape)})
onUnmounted(()=>{clearInterval(tick);document.removeEventListener('keydown',escape)})
</script>
<template>
<InboxFlow v-if="sheet==='inbox'" :token="token" @close="sheet=''" @signin="emit('signin')" />
<ProfileFlow v-else-if="sheet==='profile'" :token="token" @close="sheet=''" />
<section v-else class="home-flow" :class="{'motion-off':!motion,'refreshing':busy}" :data-state="responses.length?'home-response':items.length?'home-ready':'home-empty'">
<header class="home-header"><img :src="asset('01-brand-scenes/maugo-wordmark')" :alt="tr('MauGo')"><div><button id="magic" :aria-label="tr('Bird appearance')" @click="sheet='appearance'">✦</button><button id="settings" :aria-label="tr('Filters')" @click="openFilters">☷</button></div></header>
<div v-if="error&&sheet!=='pass-confirm'" class="home-error" role="alert">{{tr(error)}} <button v-if="!token" @click="emit('signin')">{{tr("Sign in")}}</button><button v-else :disabled="busy" @click="load()">{{tr("Retry")}}</button></div>
<div v-if="responses.length" class="response-strip"><button v-for="r in responses" :key="r.openingMessageId" @click="openLetter(r.openingMessageId)">{{tr("✉ Replied to you")}} <small>{{tr("Tap to open")}}</small></button></div>
<section class="magic-scene" :aria-busy="busy"><div class="aura"></div><img class="scene-mist" :src="asset('01-brand-scenes/mist')" alt=""><span v-if="trails" class="magic-sparks">✧ · ✦ · ✧</span>
<TransitionGroup name="birds" tag="div" class="bird-layer"><button v-for="(letter,i) in items" :key="letter.openingMessageId" class="letter-bird" :style="{'--i':i}" :aria-label="`Open letter from ${letter.sender.displayName}`" @click="openLetter(letter.openingMessageId)"><span v-if="motion" class="flight-sprite" :style="{backgroundImage:`url(${flight})`}"></span><img v-else :src="bird" alt=""><small>{{letter.sender.displayName}}</small></button></TransitionGroup>
<button id="hat" class="magic-hat" :aria-label="tr('Tap the hat to meet three new letters')" :disabled="busy" @click="load(true)"><img :src="asset('01-brand-scenes/hat')" :alt="tr('A black magic hat with a glowing green ribbon')"></button>
</section>
<p class="scene-hint">{{tr(busy?'Your little birds are on their way…':loaded&&!items.length?'No letters match just yet. Try another little wish.':'Tap a bird. Open a little story.')}}</p>
<div class="home-actions"><button id="compose" :aria-label="tr('Write a letter')" @click="sheet='compose'">{{tr("✎ Write a letter")}}</button><button id="refresh" :aria-label="tr('Refresh')" :disabled="busy" @click="load(true)">{{tr("⟳ Refresh")}}</button><button class="primary" @click="openFilters">{{tr("Find your letters")}}</button></div><nav class="home-nav"><span aria-current="page">{{tr("✧ Home")}}</span><button id="open-inbox" @click="sheet='inbox'">{{tr("Messages")}}</button><button @click="sheet='appearance'">{{tr("Choose your bird")}}</button><button id="open-profile" @click="sheet='profile'">{{tr("My profile")}}</button></nav>
<LettersFlow v-if="sheet==='letter'||sheet==='compose'" :token="token" :letter="sheet==='letter'?detail:undefined" :compose="sheet==='compose'" @close="sheet=''" @blocked="items=items.filter(i=>i.openingMessageId!==$event);responses=responses.filter(i=>i.openingMessageId!==$event)" />
<ReplyTopup v-if="passTopup" :balance="passBalance" :token="token" :required="selectedPlan?.diamonds" context="Pass" @back="returnToPass()" @funded="returnToPass(true)" />
<Transition name="sheet"><div v-if="!passTopup&&sheet&&!['letter','compose','inbox'].includes(sheet)" class="home-veil" :class="{'pass-payment-veil':sheet==='pass-confirm'}" @click.self="closeSheet">
<section class="home-sheet" :class="{'pass-payment-dialog':sheet==='pass-confirm'}" role="dialog" aria-modal="true" :data-state="sheet==='filters'?(Object.keys(filters).length?'filters-selected':active?'filters-active':'filters-free'):sheet==='appearance'?(!motion?'bird-motion-off':`bird-${birdGender}`):sheet" :aria-label="tr(sheet==='appearance'?'Choose your bird':sheet==='filters'?'Find your letters':sheet==='pass-confirm'?'Confirm Filter Pass':sheet==='pass'?'Filter Pass':'A letter for you')"><header><h2>{{tr(sheet==='appearance'?'Choose your bird':sheet==='filters'?'Find your letters':sheet==='pass-confirm'?'Confirm Filter Pass':sheet==='pass'?'Filter Pass':'A letter for you')}}</h2><button :aria-label="tr('Close')" :disabled="busy&&sheet==='pass-confirm'" @click="closeSheet">×</button></header>
<template v-if="sheet==='filters'"><p>{{tr("Gender")}}</p><div class="gender-options"><button v-for="g in [['male','♂','Man'],['female','♀','Woman'],['','∞','Everyone']]" :key="g[0]" :aria-label="tr(`Filter ${g[2]}`)" :aria-pressed="gender===g[0]" @click="gender=g[0]!"><i>{{tr(g[1])}}</i>{{tr(g[2])}}</button></div><p>{{tr("Age range")}} <button class="pass-badge" @click="sheet='pass'">{{tr("◆ Pass")}}</button><small>{{min}}–{{tr(max===50?'50+':max)}}</small></p><div class="premium-zone"><label>{{tr("Minimum age")}}<input v-model.number="min" :aria-label="tr('Minimum age')" type="range" min="18" max="50" :disabled="!active" @input="ageSet=true;max=Math.max(max,min)"></label><label>{{tr("Maximum age")}}<input v-model.number="max" :aria-label="tr('Maximum age')" type="range" min="18" max="50" :disabled="!active" @input="ageSet=true;min=Math.min(min,max)"></label><button v-if="!active" class="premium-cover" @click="sheet='pass'">{{tr("♢ Unlock age and city filters")}}</button></div><p>{{tr("City")}} <button class="pass-badge" @click="sheet='pass'">{{tr("◆ Pass")}}</button></p><select v-model="city" :aria-label="tr('City')" :disabled="!active"><option value="">{{tr("Any city")}}</option><option v-for="c in cities" :key="c">{{c}}</option></select><small class="city-source">{{tr("City options · temporary data source")}}</small><p class="pass-status">{{tr(active?`Filter Pass · ${days} days remaining`:'Choose a day pass to unlock age and city filters.')}}</p><button v-if="!active" class="unlock-pass" @click="sheet='pass'">{{tr("Unlock Filter Pass")}}</button><button class="primary" :disabled="busy" @click="sheet='';load()">{{tr("Done")}}</button></template>
<template v-else-if="sheet==='appearance'"><div id="appearance-genders" class="gender-options"><button v-for="g in ['male','female']" :key="g" :aria-pressed="birdGender===g" @click="birdGender=g"><img :src="asset(`02-bird-static/${g}-${variant}`)" alt="">{{tr(g==='male'?'Male bird':'Female bird')}}</button></div><div class="appearance-grid"><button v-for="(name,i) in variants" :key="name" :aria-pressed="variant===i+1" :aria-label="tr(`Choose ${name}`)" @click="variant=i+1"><img :src="asset(`02-bird-static/${birdGender}-${i+1}`)" alt=""><span>{{tr(name)}}</span></button></div><div class="flight-preview"><span v-if="motion" class="flight-sprite" :style="{backgroundImage:`url(${flight})`}"></span><img v-else :src="bird" alt=""><span>{{tr("Flight preview")}}</span></div><label class="switch-row">{{tr("Flight & hover")}}<input v-model="motion" type="checkbox"></label><label class="switch-row">{{tr("Magic trails")}}<input v-model="trails" type="checkbox"></label><button class="primary" @click="sheet=''">{{tr("Done")}}</button></template>
<template v-else-if="sheet==='pass'"><p>{{tr("Unlock age and city filters.")}}</p><p v-if="active">{{days}} {{tr("days remaining")}}</p><button v-for="p in pass.plans" :key="p.days" class="pass-plan" :aria-pressed="selectedPlan?.days===p.days" :disabled="busy" @click="confirmPlan(p)">{{p.days}} {{tr("day")}}{{tr(p.days>1?'s':'')}} <b>◆ {{p.diamonds}}</b></button><p v-if="!pass.plans.length">{{tr("Sign in to view available passes.")}}</p><button class="text-button" @click="sheet='filters'">{{tr("Back to filters")}}</button></template>
<template v-else-if="sheet==='pass-confirm'&&selectedPlan"><div class="pass-confirmation" :aria-busy="busy"><span class="pass-eyebrow">{{tr("Filter Pass")}}</span><div class="pass-payment-symbol"><img :src="asset('01-brand-scenes/diamond')" alt=""></div><h3>{{tr(active?'Extend':'Unlock')}} {{tr("Filter Pass ·")}} {{selectedPlan.days}} {{tr("day")}}{{tr(selectedPlan.days>1?'s':'')}}</h3><p>{{tr("Age and city filters · Valid until")}} {{validUntil}}.<br>{{tr("One-time payment. No automatic renewal.")}}</p><dl class="pass-payment-summary"><div><dt>{{tr("Plan")}}</dt><dd>{{selectedPlan.days}} {{tr("day")}}{{tr(selectedPlan.days>1?'s':'')}}</dd></div><div><dt>{{tr("Price")}}</dt><dd>{{selectedPlan.diamonds}} {{tr("diamonds")}}</dd></div><div><dt>{{tr("Total deduction")}}</dt><dd>◆ {{selectedPlan.diamonds}} {{tr("diamonds")}}</dd></div></dl><p v-if="error" role="alert" class="home-error">{{tr(error)}} {{tr("Your plan and filters are saved. Confirm again to retry.")}}</p><p>{{tr("Your balance ·")}} {{passBalance}} {{tr("diamonds")}}</p><p v-if="passNotice" role="status">{{tr(passNotice)}}</p><button v-if="passBalance<selectedPlan.diamonds" id="pass-topup" class="primary" @click="passTopup=true">{{tr("Get diamonds")}}</button><button id="confirm-pass-payment" class="primary" :disabled="busy||passBalance<selectedPlan.diamonds" @click="purchase(selectedPlan.days)">{{tr(busy?'Processing…':`Pay ${selectedPlan.diamonds} diamonds`)}}</button><button id="cancel-pass" class="text-button" :disabled="busy" @click="closeSheet">{{tr("Not now · Back to filters")}}</button></div></template>
<template v-else-if="detail"><p class="letter-meta">{{detail.sender.displayName}} · {{detail.sender.city}}</p><p class="letter-content">{{detail.content}}</p></template>
<p v-if="error&&sheet!=='pass-confirm'" role="alert" class="home-error">{{tr(error)}}</p>
</section></div></Transition>
</section>
</template>
<style src="../home.css"></style>

<style scoped>
.pass-payment-veil{align-items:center;padding:24px;background:#030805c9;backdrop-filter:blur(8px)}.pass-payment-dialog{position:relative;max-height:min(704px,92%);background:linear-gradient(145deg,#253229,#17221c);border:1px solid #d5eac51a;border-radius:28px;padding:28px 24px 16px;box-shadow:0 28px 80px #0009}.pass-payment-dialog header{margin:0}.pass-payment-dialog header h2{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.pass-payment-dialog header button{position:absolute;right:8px;top:8px;width:40px;height:40px;color:#acbcaa}.pass-eyebrow{color:#b5fa70;font-size:10px;letter-spacing:1.3px;text-transform:uppercase}.pass-confirmation{animation:pass-confirm-in .25s ease-out;text-align:center}.pass-payment-symbol{height:88px;margin:12px auto 16px;display:grid;place-items:center;background:radial-gradient(ellipse,#b5fa7026,transparent 70%)}.pass-payment-symbol img{width:88px;height:80px;object-fit:contain;filter:drop-shadow(0 8px 16px #c86afd33)}.pass-confirmation h3{font-size:22px;font-weight:600;line-height:28px;margin:8px 0 12px}.pass-confirmation>p{font-size:12px;line-height:1.8;color:#98ab8f}.pass-payment-summary{margin:24px 0;padding:8px 16px;background:#0e181566;border:1px solid #ffffff08;border-radius:16px;font-size:12px}.pass-payment-summary>div{display:flex;justify-content:space-between;gap:12px;padding:12px 0}.pass-payment-summary>div+div{border-top:1px solid #ffffff08}.pass-payment-summary dt{color:#98ab8f}.pass-payment-summary dd{margin:0;color:#cbfca5}.pass-confirmation>button{display:block;width:100%;min-height:48px;border-radius:24px;margin-top:12px}.pass-confirmation .text-button{background:none;color:#98ab8f;font-size:12px}.pass-confirmation .home-error{color:#edb39f;text-align:left;padding:12px;background:#63392d33;border-radius:12px}@keyframes pass-confirm-in{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.pass-confirmation{animation:none}}
</style>
